// Pick an image from the public Drive folder (no auth, no rclone, no cron).
//
// Source: HTML returned by https://drive.google.com/embeddedfolderview?id=<FOLDER_ID>
// which contains (file_id, filename) pairs for every file in the folder.
// Folder must be shared "Anyone with the link → Viewer".
//
// Dedup: staticData.postedNames persists across runs (filename-based,
// stable across Drive ID changes if user re-uploads). When the pool
// exhausts, the list resets so rotation continues (cycleReset=true).
//
// Caption rotation: 4-week cycle [météo → humour → QR → crew], anchored
// on Fri 2026-05-01 22:00 UTC = Sat 2026-05-02 00:00 Europe/Paris.

const httpOut = $input.first().json;
const html = (httpOut && (httpOut.data || httpOut.body || '')) + '';
if (!html || html.length < 500) {
  throw new Error('Drive folder HTML response too short. Is the folder still publicly shared?');
}

// Parse file IDs (from /file/d/<ID>/ links) and filenames (from flip-entry-title divs).
const ids = [...html.matchAll(/\/file\/d\/([a-zA-Z0-9_-]{20,})\//g)].map(m => m[1]);
const names = [...html.matchAll(/<div class="flip-entry-title">([^<]+)<\/div>/g)].map(m => m[1]);
if (ids.length === 0 || names.length === 0 || ids.length !== names.length) {
  throw new Error(`Drive HTML parse mismatch (ids=${ids.length} names=${names.length}). Folder may have changed share status, or Drive HTML format may have shifted.`);
}

const pool = [];
const seenIds = new Set();
for (let i = 0; i < ids.length; i++) {
  if (seenIds.has(ids[i])) continue;
  seenIds.add(ids[i]);
  if (/\.(jpe?g|png|webp|heic|gif)$/i.test(names[i])) {
    pool.push({ id: ids[i], name: names[i] });
  }
}
if (pool.length === 0) {
  throw new Error('No image files found in Drive folder (only non-image files present?).');
}
pool.sort((a, b) => String(a.name).localeCompare(String(b.name)));

const staticData = $getWorkflowStaticData('global');
staticData.postedNames = Array.isArray(staticData.postedNames) ? staticData.postedNames : [];

let available = pool.filter((f) => !staticData.postedNames.includes(f.name));
let cycleReset = false;
if (available.length === 0) {
  staticData.postedNames = [];
  available = pool.slice();
  cycleReset = true;
}

const pick = available[0];
staticData.postedNames.push(pick.name);

const imageUrl = `https://lh3.googleusercontent.com/d/${pick.id}=w2000`;

const EPOCH = Date.UTC(2026, 4, 1, 22, 0, 0); // Fri 2026-05-01 22:00 UTC = Sat 2026-05-02 00:00 Paris
const week = Math.floor((Date.now() - EPOCH) / (7 * 24 * 60 * 60 * 1000));
const captions = [
  // 0 — météo
  `Si la météo tient ses promesses, c'est week-end glace les pieds dans l'herbe.\n\nOn vous attend face à la mairie de La Frette-sur-Seine, samedi & dimanche, 14h–19h.\n\nCrêpes · gaufres · glaces artisanales\n#glaceenseine`,
  // 1 — humour
  `Y'a des jours où t'as juste pas envie de réfléchir. Bonne nouvelle, on a tout prévu.\n\nTu marches, tu pointes, tu manges.\nQuai de La Frette-sur-Seine, sam & dim, 14h–19h.\n#glaceenseine`,
  // 2 — QR
  `Hésiter entre douze parfums, ça fatigue. Sur place, scanne le QR du menu : un mini-jeu te tire un parfum au hasard.\n\nDécision : 0,3 seconde.\n\nCe week-end, sam & dim, 14h–19h, face à la mairie de La Frette-sur-Seine.\n#glaceenseine`,
  // 3 — crew
  `Le gang Glace en Seine te garde une place ce week-end. Banc, herbe, marches du quai — choisis ton spot.\n\nSamedi & dimanche, 14h–19h, face à la mairie de La Frette-sur-Seine.\nCrêpes · gaufres · glaces artisanales\n#glaceenseine`
];
const caption = captions[((week % captions.length) + captions.length) % captions.length];

return [{
  json: {
    week,
    pickedId: pick.id,
    pickedName: pick.name,
    imageUrl,
    caption,
    cycleReset,
    postedCount: staticData.postedNames.length,
    poolSize: pool.length
  }
}];
